/**
 * 基础认证类型定义，用于登录请求、响应、认证结果和错误处理。
 */

/**
 * 登录请求参数。
 */
export interface LoginRequest {
  /**
   * 用户名、邮箱或其他登录标识。
   */
  identifier: string;

  /**
   * 登录密码。
   */
  password: string;

  /**
   * 是否保持登录状态。
   */
  rememberMe?: boolean;
}

/**
 * 用户基础信息。
 */
export interface UserInfo {
  /**
   * 用户唯一标识。
   */
  id: string;

  /**
   * 用户名。
   */
  username: string;

  /**
   * 显示名称。
   */
  displayName?: string;

  /**
   * 邮箱地址。
   */
  email?: string;

  /**
   * 手机号码。
   */
  phoneNumber?: string;

  /**
   * 用户角色列表。
   */
  roles: string[];

  /**
   * 账号创建时间，使用 ISO 8601 字符串表示。
   */
  createdAt: string;

  /**
   * 账号最后更新时间，使用 ISO 8601 字符串表示。
   */
  updatedAt?: string;
}

/**
 * 登录响应结果。
 */
export interface LoginResponse {
  /**
   * 访问令牌。
   */
  accessToken: string;

  /**
   * 刷新令牌。
   */
  refreshToken?: string;

  /**
   * 令牌类型，通常为 Bearer。
   */
  tokenType: 'Bearer';

  /**
   * 访问令牌有效期，单位为秒。
   */
  expiresIn: number;

  /**
   * 当前登录用户信息。
   */
  user: UserInfo;
}

/**
 * 认证结果状态。
 */
export type AuthStatus = 'success' | 'failure';

/**
 * 认证错误码。
 */
export type AuthErrorCode =
  | 'INVALID_REQUEST'
  | 'INVALID_CREDENTIALS'
  | 'ACCOUNT_LOCKED'
  | 'ACCOUNT_DISABLED'
  | 'TOKEN_EXPIRED'
  | 'TOKEN_INVALID'
  | 'NETWORK_ERROR'
  | 'UNKNOWN_ERROR';

/**
 * 认证错误信息。
 */
export interface AuthError {
  /**
   * 错误码。
   */
  code: AuthErrorCode;

  /**
   * 可读的错误描述。
   */
  message: string;

  /**
   * HTTP 状态码，可选。
   */
  statusCode?: number;

  /**
   * 字段级错误信息，可选。
   */
  fieldErrors?: Record<string, string>;

  /**
   * 额外错误详情，可选。
   */
  details?: string;
}

/**
 * 登录成功后的认证结果。
 */
export interface AuthSuccessResult {
  /**
   * 是否成功。
   */
  ok: true;

  /**
   * 用户信息。
   */
  user: UserInfo;

  /**
   * 登录响应。
   */
  response: LoginResponse;
}

/**
 * 登录失败后的认证结果。
 */
export interface AuthFailureResult {
  /**
   * 是否成功。
   */
  ok: false;

  /**
   * 错误信息。
   */
  error: AuthError;
}

/**
 * 认证结果联合类型。
 */
export type AuthResult = AuthSuccessResult | AuthFailureResult;

/**
 * 可复用的登录表单数据类型。
 */
export type LoginFormValue = Pick<LoginRequest, 'identifier' | 'password'> &
  Partial<Pick<LoginRequest, 'rememberMe'>>;

/**
 * 登录结果状态。
 */
export type LoginStatus = 'success' | 'failure';

/**
 * 登录凭据。
 */
export interface LoginCredentials {
  username: string;
  password: string;
}

/**
 * 认证通过后返回的用户信息。
 */
export interface AuthenticatedUser {
  id: string;
  username: string;
  displayName?: string;
  [key: string]: unknown;
}

/**
 * 抽象认证接口。
 * 由外部注入具体实现，便于与前端/后端框架解耦。
 */
export interface Authenticator {
  authenticate(credentials: LoginCredentials): Promise<AuthenticatedUser>;
}

/**
 * 登录成功结果。
 */
export interface LoginSuccessResult {
  status: 'success';
  user: AuthenticatedUser;
  message: string;
}

/**
 * 登录失败结果。
 */
export interface LoginFailureResult {
  status: 'failure';
  message: string;
  errorCode:
    | 'INVALID_INPUT'
    | 'AUTHENTICATION_FAILED'
    | 'UNKNOWN_ERROR';
}

/**
 * 登录结果。
 */
export type LoginResult = LoginSuccessResult | LoginFailureResult;

/**
 * 登录服务配置。
 */
export interface LoginServiceOptions {
  authenticator: Authenticator;
  minUsernameLength?: number;
  minPasswordLength?: number;
}

/**
 * 登录核心服务：校验输入、调用认证接口并返回结构化结果。
 */
export class LoginService {
  private readonly authenticator: Authenticator;
  private readonly minUsernameLength: number;
  private readonly minPasswordLength: number;

  /**
   * 创建登录服务实例。
   */
  constructor(options: LoginServiceOptions) {
    this.authenticator = options.authenticator;
    this.minUsernameLength = options.minUsernameLength ?? 1;
    this.minPasswordLength = options.minPasswordLength ?? 1;
  }

  /**
   * 执行登录。
   *
   * @param credentials - 用户输入的登录凭据
   * @returns 结构化登录结果
   */
  async login(credentials: LoginCredentials): Promise<LoginResult> {
    const validationError = this.validateCredentials(credentials);
    if (validationError !== null) {
      return validationError;
    }

    try {
      const user = await this.authenticator.authenticate(credentials);
      return {
        status: 'success',
        user,
        message: '登录成功',
      };
    } catch (error: unknown) {
      return this.toFailureResult(error);
    }
  }

  private validateCredentials(
    credentials: LoginCredentials,
  ): LoginFailureResult | null {
    if (!this.isNonEmptyString(credentials.username)) {
      return {
        status: 'failure',
        message: '用户名不能为空',
        errorCode: 'INVALID_INPUT',
      };
    }

    if (!this.isNonEmptyString(credentials.password)) {
      return {
        status: 'failure',
        message: '密码不能为空',
        errorCode: 'INVALID_INPUT',
      };
    }

    if (credentials.username.trim().length < this.minUsernameLength) {
      return {
        status: 'failure',
        message: '用户名长度不符合要求',
        errorCode: 'INVALID_INPUT',
      };
    }

    if (credentials.password.length < this.minPasswordLength) {
      return {
        status: 'failure',
        message: '密码长度不符合要求',
        errorCode: 'INVALID_INPUT',
      };
    }

    return null;
  }

  private toFailureResult(error: unknown): LoginFailureResult {
    if (error instanceof Error) {
      const normalizedMessage = error.message.trim();
      if (
        normalizedMessage.length > 0 &&
        /invalid|unauthorized|forbidden|fail/i.test(normalizedMessage)
      ) {
        return {
          status: 'failure',
          message: normalizedMessage,
          errorCode: 'AUTHENTICATION_FAILED',
        };
      }

      return {
        status: 'failure',
        message: normalizedMessage || '登录失败',
        errorCode: 'UNKNOWN_ERROR',
      };
    }

    return {
      status: 'failure',
      message: '登录失败',
      errorCode: 'UNKNOWN_ERROR',
    };
  }

  private isNonEmptyString(value: unknown): value is string {
    return typeof value === 'string' && value.trim().length > 0;
  }
}

/**
 * 创建登录服务。
 *
 * @param options - 登录服务配置
 * @returns 登录服务实例
 */
export function createLoginService(options: LoginServiceOptions): LoginService {
  return new LoginService(options);
}

import assert from 'node:assert/strict';

type LoginCredentials = {
  username?: string;
  password?: string;
};

type UserRecord = {
  id: string;
  username: string;
  password: string;
  name: string;
};

type AuthResult = {
  token: string;
  user: {
    id: string;
    username: string;
    name: string;
  };
};

type UserRepository = {
  findByUsername(username: string): Promise<UserRecord | null>;
};

type TokenService = {
  sign(payload: { userId: string; username: string }): Promise<string>;
};

type LoginService = {
  login(credentials: LoginCredentials): Promise<AuthResult>;
};

class LoginServiceImpl implements LoginService {
  private readonly userRepository: UserRepository;

  private readonly tokenService: TokenService;

  public constructor(userRepository: UserRepository, tokenService: TokenService) {
    this.userRepository = userRepository;
    this.tokenService = tokenService;
  }

  public async login(credentials: LoginCredentials): Promise<AuthResult> {
    const username: string | undefined = credentials.username?.trim();
    const password: string | undefined = credentials.password;

    if (!username) {
      throw new Error('用户名不能为空');
    }

    if (!password) {
      throw new Error('密码不能为空');
    }

    const user: UserRecord | null = await this.userRepository.findByUsername(username);
    if (!user || user.password !== password) {
      throw new Error('认证失败');
    }

    const token: string = await this.tokenService.sign({ userId: user.id, username: user.username });
    return {
      token,
      user: {
        id: user.id,
        username: user.username,
        name: user.name,
      },
    };
  }
}

function createMockUserRepository(user: UserRecord | null): UserRepository {
  return {
    async findByUsername(_username: string): Promise<UserRecord | null> {
      return user;
    },
  };
}

function createMockTokenService(token: string, shouldThrow = false): TokenService {
  return {
    async sign(_payload: { userId: string; username: string }): Promise<string> {
      if (shouldThrow) {
        throw new Error('token service error');
      }
      return token;
    },
  };
}

/**
 * 运行登录服务单元测试。
 */
async function runTests(): Promise<void> {
  await testSuccessfulLogin();
  await testMissingUsername();
  await testMissingPassword();
  await testAuthenticationFailure();
  await testExceptionHandling();
}

/**
 * 测试成功登录场景。
 */
async function testSuccessfulLogin(): Promise<void> {
  const user: UserRecord = {
    id: 'u1',
    username: 'alice',
    password: 'secret',
    name: 'Alice',
  };
  const service: LoginService = new LoginServiceImpl(
    createMockUserRepository(user),
    createMockTokenService('mock-token'),
  );

  const result: AuthResult = await service.login({ username: 'alice', password: 'secret' });

  assert.equal(result.token, 'mock-token');
  assert.deepEqual(result.user, {
    id: 'u1',
    username: 'alice',
    name: 'Alice',
  });
}

/**
 * 测试用户名缺失场景。
 */
async function testMissingUsername(): Promise<void> {
  const service: LoginService = new LoginServiceImpl(
    createMockUserRepository(null),
    createMockTokenService('mock-token'),
  );

  await assert.rejects(
    async (): Promise<AuthResult> => service.login({ password: 'secret' }),
    (error: unknown): boolean => error instanceof Error && error.message === '用户名不能为空',
  );
}

/**
 * 测试密码缺失场景。
 */
async function testMissingPassword(): Promise<void> {
  const service: LoginService = new LoginServiceImpl(
    createMockUserRepository(null),
    createMockTokenService('mock-token'),
  );

  await assert.rejects(
    async (): Promise<AuthResult> => service.login({ username: 'alice' }),
    (error: unknown): boolean => error instanceof Error && error.message === '密码不能为空',
  );
}

/**
 * 测试认证失败场景。
 */
async function testAuthenticationFailure(): Promise<void> {
  const user: UserRecord = {
    id: 'u1',
    username: 'alice',
    password: 'secret',
    name: 'Alice',
  };
  const service: LoginService = new LoginServiceImpl(
    createMockUserRepository(user),
    createMockTokenService('mock-token'),
  );

  await assert.rejects(
    async (): Promise<AuthResult> => service.login({ username: 'alice', password: 'wrong' }),
    (error: unknown): boolean => error instanceof Error && error.message === '认证失败',
  );
}

/**
 * 测试异常处理场景。
 */
async function testExceptionHandling(): Promise<void> {
  const user: UserRecord = {
    id: 'u1',
    username: 'alice',
    password: 'secret',
    name: 'Alice',
  };
  const service: LoginService = new LoginServiceImpl(
    createMockUserRepository(user),
    createMockTokenService('mock-token', true),
  );

  await assert.rejects(
    async (): Promise<AuthResult> => service.login({ username: 'alice', password: 'secret' }),
    (error: unknown): boolean => error instanceof Error && error.message === 'token service error',
  );
}

void runTests();
